CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), google_sub text NOT NULL UNIQUE, email text NOT NULL, display_name text NOT NULL, timezone text NOT NULL DEFAULT 'UTC', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE user_preferences(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, settings jsonb NOT NULL);
CREATE TABLE sessions(id text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE oauth_states(id text PRIMARY KEY, kind text NOT NULL, user_id uuid REFERENCES users(id) ON DELETE CASCADE, nonce text NOT NULL, verifier text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE topics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, title text NOT NULL CHECK(length(title) BETWEEN 1 AND 200), initial_knowledge smallint CHECK(initial_knowledge BETWEEN 1 AND 5), importance smallint CHECK(importance BETWEEN 1 AND 5), target_retention real NOT NULL CHECK(target_retention BETWEEN .8 AND .97), duration integer NOT NULL CHECK(duration BETWEEN 5 AND 180), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','archived')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX topics_user ON topics(user_id,status);
CREATE TABLE topic_materials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, text text NOT NULL, url text, position integer NOT NULL, UNIQUE(topic_id,position));
CREATE TABLE tags(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, normalized text NOT NULL, UNIQUE(user_id,normalized));
CREATE TABLE topic_tags(topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, tag_id uuid NOT NULL REFERENCES tags(id) ON DELETE CASCADE, PRIMARY KEY(topic_id,tag_id));
CREATE TABLE memory_states(topic_id uuid PRIMARY KEY REFERENCES topics(id) ON DELETE CASCADE, card jsonb, stability double precision, difficulty double precision, algorithm_version text NOT NULL, parameters jsonb NOT NULL, review_count integer NOT NULL DEFAULT 0, last_review_at timestamptz);
CREATE TABLE review_schedules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id uuid NOT NULL REFERENCES topics(id) ON DELETE CASCADE, ideal_due_at timestamptz NOT NULL, scheduled_at timestamptz, duration integer NOT NULL, mode text NOT NULL DEFAULT 'automatic' CHECK(mode IN ('automatic','manual')), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','completed','cancelled')), adjustment_reason text, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_pending_topic ON review_schedules(topic_id) WHERE status='pending';
CREATE INDEX schedule_due ON review_schedules(scheduled_at) WHERE status='pending';
CREATE TABLE review_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), topic_id uuid NOT NULL REFERENCES topics(id), schedule_id uuid NOT NULL UNIQUE REFERENCES review_schedules(id), original_rating smallint NOT NULL CHECK(original_rating BETWEEN 1 AND 5), mapped_rating smallint NOT NULL, completed_at timestamptz NOT NULL, previous_state jsonb, new_state jsonb NOT NULL, fsrs_log jsonb NOT NULL, algorithm_version text NOT NULL, parameters jsonb NOT NULL, corrected_at timestamptz);
CREATE TABLE review_corrections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES review_logs(id), old_rating smallint NOT NULL, new_rating smallint NOT NULL, old_state jsonb NOT NULL, corrected_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE calendar_connections(user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, calendar_id text, encrypted_tokens text NOT NULL, scopes text NOT NULL, sync_token text, channel_id text, channel_token text, resource_id text, channel_expires_at timestamptz, connected boolean NOT NULL DEFAULT true, last_sync_at timestamptz, error text);
CREATE TABLE calendar_events(schedule_id uuid PRIMARY KEY REFERENCES review_schedules(id), google_event_id text NOT NULL UNIQUE, etag text, sync_status text NOT NULL DEFAULT 'pending', deletion_count integer NOT NULL DEFAULT 0, last_deleted_at timestamptz);
CREATE TABLE sync_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','running','done','failed')), attempts integer NOT NULL DEFAULT 0, retry_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, idempotency_key text NOT NULL UNIQUE, error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX jobs_ready ON sync_jobs(status,retry_at);
